-- Intake cell: the X (Twitter) feed (x-post, x-sighting, x-watch, x-query), added 2026-10-26.
-- Posts are upserted on post_id; a sighting is one post seen by one query for one chief in one pull.
-- Do not edit once applied; add a new migration.

CREATE TABLE intake.x_posts (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    post_id                  text NOT NULL CHECK (length(post_id) <= 32 AND length(post_id) >= 1),
    post_url                 text CHECK (post_url IS NULL OR (length(post_url) <= 300)),
    author_handle            text CHECK (author_handle IS NULL OR (length(author_handle) <= 64)),
    posted_at                timestamptz,
    text                     text CHECK (text IS NULL OR (length(text) <= 30000)),
    likes                    bigint CHECK (likes IS NULL OR (likes >= 0)),
    reposts                  bigint CHECK (reposts IS NULL OR (reposts >= 0)),
    replies                  bigint CHECK (replies IS NULL OR (replies >= 0)),
    views                    bigint CHECK (views IS NULL OR (views >= 0)),
    first_collected_at       timestamptz,
    last_collected_at        timestamptz,
    last_pull_id             text CHECK (last_pull_id IS NULL OR (length(last_pull_id) <= 96)),
    exported_at              timestamptz,
    text_purged_at           timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, post_id)
);
CREATE UNIQUE INDEX x_posts_legacy ON intake.x_posts (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX x_posts_author_handle ON intake.x_posts (workspace_id, author_handle);
CREATE INDEX x_posts_post_id ON intake.x_posts (workspace_id, post_id);

CREATE TABLE intake.x_sightings (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    pull_id                  text NOT NULL CHECK (length(pull_id) <= 96 AND length(pull_id) >= 1),
    post_id                  text NOT NULL CHECK (length(post_id) <= 32 AND length(post_id) >= 1),
    collected_at             timestamptz NOT NULL,
    requesting_chief         text NOT NULL CHECK (length(requesting_chief) <= 64 AND length(requesting_chief) >= 1),
    watch_type               text CHECK (watch_type IS NULL OR (length(watch_type) <= 32)),
    watch_value              text CHECK (watch_value IS NULL OR (length(watch_value) <= 200)),
    query_id                 text NOT NULL CHECK (length(query_id) <= 64 AND length(query_id) >= 1),
    tag                      text CHECK (tag IS NULL OR (length(tag) <= 300)),
    score                    double precision,
    top                      boolean,
    likes                    bigint CHECK (likes IS NULL OR (likes >= 0)),
    reposts                  bigint CHECK (reposts IS NULL OR (reposts >= 0)),
    replies                  bigint CHECK (replies IS NULL OR (replies >= 0)),
    views                    bigint CHECK (views IS NULL OR (views >= 0)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, pull_id, post_id, query_id, requesting_chief)
);
CREATE UNIQUE INDEX x_sightings_legacy ON intake.x_sightings (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX x_sightings_post_id ON intake.x_sightings (workspace_id, post_id);
CREATE INDEX x_sightings_pull_id ON intake.x_sightings (workspace_id, pull_id);
CREATE INDEX x_sightings_query_id ON intake.x_sightings (workspace_id, query_id);
CREATE INDEX x_sightings_requesting_chief ON intake.x_sightings (workspace_id, requesting_chief);
CREATE INDEX x_sightings_watch_type ON intake.x_sightings (workspace_id, watch_type);

CREATE TABLE intake.x_watchlist (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    requesting_chief         text NOT NULL CHECK (length(requesting_chief) <= 64 AND length(requesting_chief) >= 1),
    type                     text NOT NULL CHECK (length(type) <= 32 AND length(type) >= 1),
    value                    text NOT NULL CHECK (length(value) <= 200 AND length(value) >= 1),
    purpose                  text CHECK (purpose IS NULL OR (length(purpose) <= 500)),
    added_date               date,
    last_used                timestamptz,
    tag                      text CHECK (tag IS NULL OR (length(tag) <= 300)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, requesting_chief, type, value)
);
CREATE UNIQUE INDEX x_watchlist_legacy ON intake.x_watchlist (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX x_watchlist_requesting_chief ON intake.x_watchlist (workspace_id, requesting_chief);
CREATE INDEX x_watchlist_tag ON intake.x_watchlist (workspace_id, tag);
CREATE INDEX x_watchlist_type ON intake.x_watchlist (workspace_id, type);

CREATE TABLE intake.x_query_plan (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    query_id                 text NOT NULL CHECK (length(query_id) <= 64 AND length(query_id) >= 1),
    query                    text NOT NULL CHECK (length(query) <= 1000 AND length(query) >= 1),
    requesting_chiefs        text CHECK (requesting_chiefs IS NULL OR (length(requesting_chiefs) <= 300)),
    tags                     text CHECK (tags IS NULL OR (length(tags) <= 300)),
    watchlist_rows           text CHECK (watchlist_rows IS NULL OR (length(watchlist_rows) <= 500)),
    priority                 integer,
    last_since_id            text CHECK (last_since_id IS NULL OR (length(last_since_id) <= 32)),
    last_run_at              timestamptz,
    runs                     integer CHECK (runs IS NULL OR (runs >= 0)),
    calls_total              integer CHECK (calls_total IS NULL OR (calls_total >= 0)),
    posts_total              integer CHECK (posts_total IS NULL OR (posts_total >= 0)),
    new_posts_last           integer CHECK (new_posts_last IS NULL OR (new_posts_last >= 0)),
    avg_yield                double precision,
    status                   text CHECK (status IS NULL OR (length(status) <= 32)),
    calls_last_run           integer CHECK (calls_last_run IS NULL OR (calls_last_run >= 0)),
    yield_last6              text CHECK (yield_last6 IS NULL OR (length(yield_last6) <= 200)),
    query_type               text CHECK (query_type IS NULL OR (length(query_type) <= 32)),
    lang_filter              text CHECK (lang_filter IS NULL OR (length(lang_filter) <= 32)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, query_id)
);
CREATE UNIQUE INDEX x_query_plan_legacy ON intake.x_query_plan (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX x_query_plan_query_id ON intake.x_query_plan (workspace_id, query_id);
CREATE INDEX x_query_plan_query_type ON intake.x_query_plan (workspace_id, query_type);
CREATE INDEX x_query_plan_status ON intake.x_query_plan (workspace_id, status);

ALTER TABLE intake.create_keys DROP CONSTRAINT create_keys_kind_check;
ALTER TABLE intake.create_keys ADD CONSTRAINT create_keys_kind_check CHECK (kind IN ('source', 'intake', 'intake-event', 'x-post', 'x-sighting', 'x-watch', 'x-query'));

-- Search and export read by time; the retention sweep reads exported posts by collection time.
CREATE INDEX x_posts_last_collected_at ON intake.x_posts (workspace_id, last_collected_at);
CREATE INDEX x_sightings_collected_at ON intake.x_sightings (workspace_id, collected_at);

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['x_posts', 'x_sightings', 'x_watchlist', 'x_query_plan'] LOOP
        EXECUTE format('ALTER TABLE intake.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE intake.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON intake.%I'
                       ' USING (workspace_id = intake.current_workspace())'
                       ' WITH CHECK (workspace_id = intake.current_workspace())', t);
    END LOOP;
END
$$;

GRANT SELECT, INSERT, UPDATE, DELETE ON intake.x_posts, intake.x_sightings, intake.x_watchlist, intake.x_query_plan TO intake_api;
GRANT USAGE ON SEQUENCE intake.x_posts_id_seq, intake.x_sightings_id_seq, intake.x_watchlist_id_seq, intake.x_query_plan_id_seq TO intake_api;
